// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.data.allScenes = item.json.data.allScenes.filter(x => (x?.files?.[0]?.path || "").includes('redgifs'))

  let result = []
  for(let s of item.json.data.allScenes){

    let f = s.files?.[0]?.path
    if(!f){
      continue
    }

    let name =  f.split('/')
    name = name[name.length -1]
    name = name.split('.')
    name = name.slice(0, name.length -1)
    name = name.join('.')

    name = name.replace('redgifs_', '')

    name = "https://www.redgifs.com/watch/" + name
    if (s.url != name){
      s.url = name
      result.push(s)
    }
  }
  item.json = {result: result}
}

return $input.all();

